function eligibility( $rez, $flow, $flow_class, $email, $context ) {
		if ( ! in_array( $flow, array( 'post_purchase_2d', 'post_purchase_7d', 'post_purchase_14d' ), true ) ) {
			return $rez;
		}
		if ( is_array( $rez ) && isset( $rez['allowed'] ) && ! $rez['allowed'] ) { return $rez; }
		$order_id = is_array( $context ) && isset( $context['order_id'] ) ? (int) $context['order_id'] : 0;
		if ( ! $order_id ) { return $rez; }
		$order = wc_get_order( $order_id );
		if ( ! $order ) {
			return array( 'allowed' => false, 'reason' => 'order_gone', 'terminal' => true );
		}
		if ( in_array( $order->get_status(), self::DEAD_STATUSES, true ) ) {
			return array( 'allowed' => false, 'reason' => 'order_dead_' . $order->get_status(), 'terminal' => true );
		}
		if ( (float) $order->get_total_refunded() > 0 ) {
			return array( 'allowed' => false, 'reason' => 'order_refunded', 'terminal' => true );
		}
		return $rez;
	}

